# Merch Forge · owner-local image provider setup (separate from product UI)
Set-StrictMode -Version 2.0
$ErrorActionPreference='Stop'
. (Join-Path $PSScriptRoot 'Modules\Forge.GenerationAuthority.ps1')
Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing
$root=Join-Path $env:LOCALAPPDATA 'MerchForge';$secretDir=Join-Path $root 'provider-secrets';$secretPath=Join-Path $secretDir 'openai-image.sec';$configPath=Join-Path $root 'provider-config.json';if(-not(Test-Path $secretDir)){New-Item -ItemType Directory -Path $secretDir -Force|Out-Null}
function FirstLiveCompleted([string]$StateRoot) {
    return (Test-ForgeFirstLiveAuthority $StateRoot 'openai_image_api')
}
$firstLiveCompleted=FirstLiveCompleted $root
$form=New-Object Windows.Forms.Form;$form.Text='Merch Forge · Image Provider';$form.Width=620;$form.Height=390;$form.StartPosition='CenterScreen';$form.FormBorderStyle='FixedDialog';$form.MaximizeBox=$false
$label=New-Object Windows.Forms.Label;$label.Left=24;$label.Top=20;$label.Width=555;$label.Height=42;$label.Text='OpenAI Image API key. Leave blank to keep the existing key. Stored locally with Windows DPAPI for this Windows user; never written into a Forge package.';$form.Controls.Add($label)
$keyBox=New-Object Windows.Forms.TextBox;$keyBox.Left=24;$keyBox.Top=70;$keyBox.Width=555;$keyBox.UseSystemPasswordChar=$true;$form.Controls.Add($keyBox)
$enable=New-Object Windows.Forms.CheckBox;$enable.Left=24;$enable.Top=110;$enable.Width=555;$enable.Text='Enable paid image generation after an explicit Generate click';$form.Controls.Add($enable)
$profileLabel=New-Object Windows.Forms.Label;$profileLabel.Left=24;$profileLabel.Top=148;$profileLabel.Width=90;$profileLabel.Text='Profile';$form.Controls.Add($profileLabel)
$profile=New-Object Windows.Forms.ComboBox;$profile.Left=110;$profile.Top=144;$profile.Width=300;$profile.DropDownStyle='DropDownList';[void]$profile.Items.Add('Smoke — Flare / 1024 / medium / 1');[void]$profile.Items.Add('Draft — Flare / 1024 / medium / 2');[void]$profile.Items.Add('Final — Sunburst / 2048 / high / 3');$profile.SelectedIndex=0;$form.Controls.Add($profile)
$limitLabel=New-Object Windows.Forms.Label;$limitLabel.Left=24;$limitLabel.Top=190;$limitLabel.Width=180;$limitLabel.Text='Daily paid-request ceiling';$form.Controls.Add($limitLabel)
$limit=New-Object Windows.Forms.ComboBox;$limit.Left=210;$limit.Top=186;$limit.Width=90;$limit.DropDownStyle='DropDownList';foreach($x in @(1,3,5,10,20)){[void]$limit.Items.Add([string]$x)};$limit.SelectedItem='1';$form.Controls.Add($limit)
$note=New-Object Windows.Forms.Label;$note.Left=24;$note.Top=225;$note.Width=555;$note.Height=42;$note.Text='Before the first completed live generation, Smoke + 1 request/day is mandatory. Draft/Final unlock after that milestone. Each job still permits one provider request and Forge never retries a paid request automatically.';$form.Controls.Add($note)
$save=New-Object Windows.Forms.Button;$save.Left=24;$save.Top=285;$save.Width=160;$save.Text='Save configuration';$form.Controls.Add($save)
$disable=New-Object Windows.Forms.Button;$disable.Left=198;$disable.Top=285;$disable.Width=160;$disable.Text='Disable provider';$form.Controls.Add($disable)
$remove=New-Object Windows.Forms.Button;$remove.Left=372;$remove.Top=285;$remove.Width=100;$remove.Text='Remove key';$form.Controls.Add($remove)
$close=New-Object Windows.Forms.Button;$close.Left=486;$close.Top=285;$close.Width=93;$close.Text='Close';$form.Controls.Add($close)
$utf8=New-Object Text.UTF8Encoding -ArgumentList $false
if(Test-Path -LiteralPath $configPath -PathType Leaf){try{$old=Get-Content -LiteralPath $configPath -Raw -Encoding UTF8|ConvertFrom-Json;$enable.Checked=[bool]$old.enabled;$pk=[string]$old.profile_key;if($firstLiveCompleted){if($pk-eq'final'){$profile.SelectedIndex=2}elseif($pk-eq'draft'){$profile.SelectedIndex=1}else{$profile.SelectedIndex=0};$dl=[string]$old.daily_request_limit;if(@('1','3','5','10','20') -contains $dl){$limit.SelectedItem=$dl}}else{$profile.SelectedIndex=0;$limit.SelectedItem='1'}}catch{}}
$save.Add_Click({try{$key=$keyBox.Text.Trim();if($key){$secure=ConvertTo-SecureString $key -AsPlainText -Force;$enc=$secure|ConvertFrom-SecureString;[IO.File]::WriteAllText($secretPath,$enc,$utf8)}elseif(-not(Test-Path -LiteralPath $secretPath -PathType Leaf) -and [string]::IsNullOrWhiteSpace(([string]$env:OPENAI_API_KEY).Trim())){[Windows.Forms.MessageBox]::Show('Enter an API key, or set OPENAI_API_KEY, before enabling the provider.','Merch Forge')|Out-Null;if($enable.Checked){return}};$profileKey=if($profile.SelectedIndex-eq2){'final'}elseif($profile.SelectedIndex-eq1){'draft'}else{'smoke'};$daily=[int]$limit.SelectedItem;if(-not(FirstLiveCompleted $root) -and ($profileKey-ne'smoke' -or $daily-ne1)){[Windows.Forms.MessageBox]::Show('First live generation safety is active. Use Smoke with a daily request ceiling of 1 until one billable live result is successfully imported.','Merch Forge')|Out-Null;return};if($profileKey-eq'final'){$model='gpt-image-2.5-sunburst-2026-09-08';$size='2048x2048';$quality='high';$count=3}elseif($profileKey-eq'draft'){$model='gpt-image-2.5-flare-2026-09-08';$size='1024x1024';$quality='medium';$count=2}else{$model='gpt-image-2.5-flare-2026-09-08';$size='1024x1024';$quality='medium';$count=1};$cfg=[ordered]@{schema='forge.local_generation_provider_config.v3';provider_key='openai_image_api';enabled=[bool]$enable.Checked;profile_key=$profileKey;model=$model;size=$size;quality=$quality;background='transparent';output_format='png';output_count=$count;daily_request_limit=$daily;updated_at=[DateTime]::UtcNow.ToString('o')};[IO.File]::WriteAllText($configPath,($cfg|ConvertTo-Json -Depth 10),$utf8);$keyBox.Text='';[Windows.Forms.MessageBox]::Show('Provider configuration saved. Run the local doctor before generating.','Merch Forge')|Out-Null}catch{[Windows.Forms.MessageBox]::Show($_.Exception.Message,'Merch Forge')|Out-Null}})
$disable.Add_Click({try{$cfg=[ordered]@{schema='forge.local_generation_provider_config.v3';provider_key='openai_image_api';enabled=$false;profile_key='smoke';model='gpt-image-2.5-flare-2026-09-08';size='1024x1024';quality='medium';background='transparent';output_format='png';output_count=1;daily_request_limit=1;updated_at=[DateTime]::UtcNow.ToString('o')};[IO.File]::WriteAllText($configPath,($cfg|ConvertTo-Json -Depth 10),$utf8);$enable.Checked=$false;[Windows.Forms.MessageBox]::Show('Automatic image generation disabled.','Merch Forge')|Out-Null}catch{[Windows.Forms.MessageBox]::Show($_.Exception.Message,'Merch Forge')|Out-Null}})
$remove.Add_Click({try{if(Test-Path -LiteralPath $secretPath -PathType Leaf){Remove-Item -LiteralPath $secretPath -Force};$keyBox.Text='';[Windows.Forms.MessageBox]::Show('Stored provider key removed for this Windows user.','Merch Forge')|Out-Null}catch{[Windows.Forms.MessageBox]::Show($_.Exception.Message,'Merch Forge')|Out-Null}})
$close.Add_Click({$form.Close()});[void]$form.ShowDialog()
